#requires -version 5.1
# V18 FINAL 1.0.10: production builder after RC5 normal-launch validation and RC6 ticket E2E validation; synthetic test hook is not included.
# V8 repair engine, V7 version/update controls and V6 atomic self-updater are preserved.
[CmdletBinding()]
param(
    [string]$PackageRoot = "",
    [string]$LauncherVersion = "1.1.1",
    [string]$UpdateManifestUrl = "https://raw.githubusercontent.com/eliaauditore/AotR-8P-WotR/main/manifest.json",
    [string]$UpdateBinaryUrl = "https://raw.githubusercontent.com/eliaauditore/AotR-8P-WotR/main/AotR%208P%20WotR%20Mod.exe",
    [switch]$EmitGitHubBundle,
    [switch]$BundleOnly
)

$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

$versionCore = ($LauncherVersion -split '-',2)[0]
$parsedVersion = $null
if (-not [Version]::TryParse($versionCore, [ref]$parsedVersion)) {
    throw "LauncherVersion must start with a valid numeric version such as 1.0.0 or 1.0.1-test."
}
$fileVersion = ('{0}.{1}.{2}.{3}' -f $parsedVersion.Major, [Math]::Max(0,$parsedVersion.Minor), [Math]::Max(0,$parsedVersion.Build), [Math]::Max(0,$parsedVersion.Revision))

function Get-Sha256([string]$Path) {
    $stream = [IO.File]::OpenRead($Path)
    try {
        $sha = [Security.Cryptography.SHA256]::Create()
        try {
            ([BitConverter]::ToString($sha.ComputeHash($stream))).Replace("-","").ToUpperInvariant()
        }
        finally {
            $sha.Dispose()
        }
    }
    finally {
        $stream.Dispose()
    }
}

if ([string]::IsNullOrWhiteSpace($PackageRoot)) {
    $PackageRoot = $PSScriptRoot
}
if ([string]::IsNullOrWhiteSpace($PackageRoot) -and $MyInvocation.MyCommand.Path) {
    $PackageRoot = Split-Path -Parent $MyInvocation.MyCommand.Path
}
if ([string]::IsNullOrWhiteSpace($PackageRoot)) {
    throw "Could not determine package root. Pass -PackageRoot explicitly."
}
$PackageRoot = [IO.Path]::GetFullPath($PackageRoot)
$Launcher = Join-Path $PackageRoot "AotR 8P WotR Mod.exe"
$Icon = Join-Path $PackageRoot "assets\launcher.ico"
$Skin = Join-Path $PackageRoot "internal\assets\launcher_skin.png"
$Ui = Join-Path $PackageRoot "payload\!!!WOTR_8P_UI_TEST.big"
$Paper = Join-Path $PackageRoot "payload\data\ini\campaigns\scenarios\PaperScenario001.inc"

$ExpectedUi = "827988C328E010A598BFAD16C9BFF830C3F904EAF1640F162C8124E8C6ABA376"
$ExpectedPaper = "3FF683843190A323DE9299C17DCD36AF24C5C00473119478E3FAF068BF904E43"
$ExpectedSkin = "BA044C14023AAF21FC4822D068C07E8991DC6CAEDAC6BCD5F1B50935BA9C7AC6"

foreach ($p in @($Launcher,$Icon,$Skin,$Ui,$Paper)) {
    if (-not (Test-Path -LiteralPath $p -PathType Leaf)) {
        throw "Required RC5 file missing: $p"
    }
}

if ((Get-Sha256 $Ui) -ne $ExpectedUi) { throw "RC5 UI payload hash mismatch. Aborting." }
if ((Get-Sha256 $Paper) -ne $ExpectedPaper) { throw "RC5 PaperScenario hash mismatch. Aborting." }
if ((Get-Sha256 $Skin) -ne $ExpectedSkin) { throw "Launcher skin hash mismatch. Aborting." }

# The generated launcher targets .NET Framework 4.x and therefore must reference
# Windows PowerShell 5.1's System.Management.Automation.dll. When this builder is
# launched from PowerShell 7+, the currently loaded automation assembly targets
# modern .NET and cannot be consumed by the .NET Framework csc.exe below.
$windowsPowerShell = Join-Path $env:WINDIR "System32\WindowsPowerShell\v1.0\powershell.exe"
$automation = $null

if (Test-Path -LiteralPath $windowsPowerShell -PathType Leaf) {
    $automation = (& $windowsPowerShell -NoLogo -NoProfile -NonInteractive -Command "[System.Management.Automation.PSObject].Assembly.Location" 2>$null | Select-Object -First 1)
    if ($automation) { $automation = [string]$automation.Trim() }
}

# Fallback for a builder already running inside Windows PowerShell 5.1.
if ([string]::IsNullOrWhiteSpace($automation) -or -not (Test-Path -LiteralPath $automation -PathType Leaf)) {
    $candidate = [System.Management.Automation.PSObject].Assembly.Location
    if ($PSVersionTable.PSEdition -eq "Desktop" -and $candidate -and (Test-Path -LiteralPath $candidate -PathType Leaf)) {
        $automation = $candidate
    }
}

if ([string]::IsNullOrWhiteSpace($automation) -or -not (Test-Path -LiteralPath $automation -PathType Leaf)) {
    throw "Could not resolve the Windows PowerShell 5.1 System.Management.Automation.dll required by the .NET Framework launcher compiler."
}
Write-Host ("Windows PowerShell automation DLL: " + $automation) -ForegroundColor DarkGray

$csc = @(
    (Join-Path $env:WINDIR "Microsoft.NET\Framework64\v4.0.30319\csc.exe"),
    (Join-Path $env:WINDIR "Microsoft.NET\Framework\v4.0.30319\csc.exe")
) | Where-Object { Test-Path -LiteralPath $_ -PathType Leaf } | Select-Object -First 1

if (-not $csc) { throw "Windows .NET Framework C# compiler csc.exe was not found." }

$tempRoot = Join-Path $env:TEMP ("AotR8P_SINGLE_EXE_BUILD_" + [Guid]::NewGuid().ToString("N"))
New-Item -ItemType Directory -Force -Path $tempRoot | Out-Null

try {
    $csPath = Join-Path $tempRoot "launcher.cs"
    $manifestPath = Join-Path $tempRoot "launcher.manifest"
    $newExe = Join-Path $tempRoot "AotR 8P WotR Mod.exe"

    $template = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(@'

'@))

    $skinRaw = [IO.File]::ReadAllBytes($Skin)
    $skinBuffer = [IO.MemoryStream]::new()
    try {
        $skinGzip = [IO.Compression.GZipStream]::new($skinBuffer,[IO.Compression.CompressionMode]::Compress,$true)
        try { $skinGzip.Write($skinRaw,0,$skinRaw.Length) }
        finally { $skinGzip.Dispose() }
        $skinGzipBase64 = [Convert]::ToBase64String($skinBuffer.ToArray())
    }
    finally { $skinBuffer.Dispose() }
    $skinSha256 = Get-Sha256 $Skin
    $safeUrl = $UpdateManifestUrl.Replace("\", "\\").Replace('"','\"')
    $safeVersion = $LauncherVersion.Replace("\", "\\").Replace('"','\"')
    $source = $template.Replace("__UPDATE_URL__", $safeUrl).Replace("__LAUNCHER_VERSION__", $safeVersion).Replace("__FILE_VERSION__", $fileVersion).Replace("__ISSUE33_SKIN_GZIP_BASE64__", $skinGzipBase64).Replace("__ISSUE33_SKIN_SHA256__", $skinSha256)

    [IO.File]::WriteAllText($csPath, $source, (New-Object Text.UTF8Encoding($false)))

    $manifest = @'
<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<assembly xmlns="urn:schemas-microsoft-com:asm.v1" manifestVersion="1.0">
  <assemblyIdentity version="1.0.0.0" name="eliaauditore.AotR8PWotRMod.SingleExe"/>
  <trustInfo xmlns="urn:schemas-microsoft-com:asm.v3">
    <security>
      <requestedPrivileges>
        <requestedExecutionLevel level="requireAdministrator" uiAccess="false"/>
      </requestedPrivileges>
    </security>
  </trustInfo>
  <application xmlns="urn:schemas-microsoft-com:asm.v3">
    <windowsSettings>
      <dpiAware xmlns="http://schemas.microsoft.com/SMI/2005/WindowsSettings">true</dpiAware>
    </windowsSettings>
  </application>
</assembly>
'@
    [IO.File]::WriteAllText($manifestPath,$manifest,(New-Object Text.UTF8Encoding($false)))

    Write-Host "Compiling embedded Single-EXE launcher..." -ForegroundColor Cyan

    $out = & $csc `
        "/nologo" `
        "/target:winexe" `
        "/optimize+" `
        "/platform:anycpu" `
        "/reference:System.Windows.Forms.dll" `
        "/reference:System.Web.Extensions.dll" `
        "/reference:$automation" `
        "/win32icon:$Icon" `
        "/win32manifest:$manifestPath" `
        "/out:$newExe" `
        "$csPath" 2>&1

    if ($LASTEXITCODE -ne 0 -or -not (Test-Path -LiteralPath $newExe -PathType Leaf)) {
        $out | ForEach-Object { Write-Host $_ -ForegroundColor Red }
        throw "Single-EXE compilation failed."
    }

    $bytes = [IO.File]::ReadAllBytes($newExe)
    if ($bytes.Length -lt 4096 -or $bytes[0] -ne 0x4D -or $bytes[1] -ne 0x5A) {
        throw "Compiled file is not a valid Windows PE executable."
    }

    $builtHash = Get-Sha256 $newExe

    if ($EmitGitHubBundle) {
        $bundleRoot = Join-Path $PackageRoot "_GITHUB_UPDATE"
        $bundleUpdate = $bundleRoot
        if (Test-Path -LiteralPath $bundleRoot) {
            Remove-Item -LiteralPath $bundleRoot -Recurse -Force
        }
        New-Item -ItemType Directory -Force -Path $bundleUpdate | Out-Null
        Copy-Item -LiteralPath $newExe -Destination (Join-Path $bundleUpdate "AotR 8P WotR Mod.exe") -Force

        # Keep schema=1 so already released launchers can still self-update.
        # Newer launchers simply consume the additional repair/payload metadata.
        $repoRaw = "https://raw.githubusercontent.com/eliaauditore/AotR-8P-WotR/main"
        $manifestObject = [ordered]@{
            schema = 1
            launcher_version = $LauncherVersion
            launcher_url = $UpdateBinaryUrl
            launcher_sha256 = $builtHash
            mandatory = $false

            repair_manifest_url = "$repoRaw/repair-manifest.json"
            ui_url = "$repoRaw/payload_ui.big"
            ui_sha256 = $ExpectedUi
            paper_url = "$repoRaw/payload_paper.inc"
            paper_sha256 = $ExpectedPaper
        }
        $manifestJson = $manifestObject | ConvertTo-Json -Depth 6
        [IO.File]::WriteAllText(
            (Join-Path $bundleUpdate "manifest.json"),
            $manifestJson + [Environment]::NewLine,
            (New-Object Text.UTF8Encoding($false))
        )

        # Repair payloads are immutable verified copies. AUTO REPAIR will only install
        # them after their SHA256 matches the hashes above.
        Copy-Item -LiteralPath $Ui -Destination (Join-Path $bundleUpdate "payload_ui.big") -Force
        Copy-Item -LiteralPath $Paper -Destination (Join-Path $bundleUpdate "payload_paper.inc") -Force

        # Remote plans may ONLY select actions from the launcher's built-in allow-list.
        # This file can therefore tune repair recipes without shipping executable code.
        $repairManifest = [ordered]@{
            schema = 1
            generated_for_launcher = $LauncherVersion
            plans = [ordered]@{
                "A8P-INSTALL-001" = [ordered]@{
                    actions = @("reset_install","retry_launch")
                }
                "A8P-PAYLOAD-UI-001" = [ordered]@{
                    actions = @("repair_payloads","reset_runtime","retry_launch")
                }
                "A8P-PAYLOAD-PAPER-001" = [ordered]@{
                    actions = @("repair_payloads","reset_runtime","retry_launch")
                }
                "A8P-LEGACY-001" = [ordered]@{
                    actions = @("stop_old_dev_launchers","stop_legacy_runtime","retry_launch")
                }
                "A8P-PROCESS-001" = [ordered]@{
                    actions = @("stop_legacy_runtime","stop_failed_game","retry_launch")
                }
                "A8P-RUNTIME-001" = [ordered]@{
                    actions = @("stop_legacy_runtime","stop_failed_game","reset_runtime","repair_payloads","retry_launch")
                }
                "A8P-GAMEPROC-001" = [ordered]@{
                    actions = @("stop_legacy_runtime","stop_failed_game","reset_runtime","retry_launch")
                }
                "A8P-PERMISSION-001" = [ordered]@{
                    actions = @("stop_failed_game","retry_launch")
                }
                "A8P-COMPAT-001" = [ordered]@{
                    actions = @("check_launcher_update")
                    protected = $true
                }
                "A8P-ENGINE-001" = [ordered]@{
                    actions = @("stop_legacy_runtime","stop_failed_game","reset_runtime","clear_compat_cache","retry_launch")
                }
            }
        }
        [IO.File]::WriteAllText(
            (Join-Path $bundleUpdate "repair-manifest.json"),
            (($repairManifest | ConvertTo-Json -Depth 8) + [Environment]::NewLine),
            (New-Object Text.UTF8Encoding($false))
        )
    }

    if (-not $BundleOnly) {
        $backupRoot = Join-Path $env:LOCALAPPDATA "AotR 8P WotR Mod\seed_backup"
        New-Item -ItemType Directory -Force -Path $backupRoot | Out-Null
        $backup = Join-Path $backupRoot ("AotR 8P WotR Mod_PRE_" + $LauncherVersion.Replace('.','_') + "_" + (Get-Date -Format "yyyyMMdd_HHmmss") + ".exe")
        Copy-Item -LiteralPath $Launcher -Destination $backup -Force
        Copy-Item -LiteralPath $newExe -Destination $Launcher -Force

        Write-Host ""
        Write-Host "[OK] Single-EXE launcher installed locally." -ForegroundColor Green
        Write-Host ("Launcher : " + $Launcher)
        Write-Host ("Version  : " + $LauncherVersion)
        Write-Host ("SHA256   : " + (Get-Sha256 $Launcher))
        Write-Host ("Backup   : " + $backup)
        Write-Host ("Updater  : " + $UpdateManifestUrl) -ForegroundColor Green
    } else {
        Write-Host ""
        Write-Host "[OK] Update launcher built without replacing the local launcher." -ForegroundColor Green
        Write-Host ("Version  : " + $LauncherVersion)
        Write-Host ("SHA256   : " + $builtHash)
    }

    if ($EmitGitHubBundle) {
        Write-Host ("GitHub   : " + (Join-Path $PackageRoot "_GITHUB_UPDATE")) -ForegroundColor Cyan
        Write-Host "          Upload ALL FIVE files in that folder to the repository ROOT." -ForegroundColor Cyan
        Write-Host "          EXE + manifest.json + repair-manifest.json + payload_ui.big + payload_paper.inc" -ForegroundColor Cyan
    }
    Write-Host ""
    Write-Host "GUI + diagnostics + REPORT ERROR + MESSAGES + engine + FINAL_STABLE_V7 + AUTO REPAIR remain embedded in the EXE." -ForegroundColor Green
    Write-Host "No external launcher/engine PowerShell files are executed by the launcher."
}
finally {
    Remove-Item -LiteralPath $tempRoot -Recurse -Force -ErrorAction SilentlyContinue
}
